DEFS='''<defs><linearGradient id="ouro" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#fff1a8"/><stop offset=".45" stop-color="#f6c443"/><stop offset="1" stop-color="#c98a12"/></linearGradient>
<linearGradient id="holo" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#7f7fd5"/><stop offset=".5" stop-color="#86a8e7"/><stop offset="1" stop-color="#91eae4"/></linearGradient>
<linearGradient id="bg" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="{c1}"/><stop offset="1" stop-color="{c2}"/></linearGradient>
<radialGradient id="luz" cx=".3" cy=".2" r=".9"><stop offset="0" stop-color="#fff" stop-opacity=".28"/><stop offset=".6" stop-color="#fff" stop-opacity="0"/></radialGradient></defs>'''
def svg(c1,c2,arte,modo,u='x'):
    # modo: any = cantos arredondados, arte 100%; full = quadrado cheio (iOS/maskable), escala da arte
    esc={'any':1,'full':0.92,'mask':0.74}[modo]; r=22 if modo=='any' else 0
    t=50-50*esc
    out= f'''<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100" width="100%" height="100%">{DEFS.format(c1=c1,c2=c2)}
<rect width="100" height="100" rx="{r}" fill="url(#bg)"/><rect width="100" height="100" rx="{r}" fill="url(#luz)"/>
<g transform="translate({t} {t}) scale({esc})">{arte}</g></svg>'''
    for i in ['ouro','holo','bg','luz']: out=out.replace(f'id="{i}"',f'id="{i}_{u}"').replace(f'url(#{i})',f'url(#{i}_{u})')
    return out
